class item;
class script_object;

class entity
{
public:
  item *find_like_item(item *);
  bool add_item(item *);
};

class world_dynamics_system
{
public:
  script_object *get_current_level_global_script_object() const;
  void guarantee_active(entity *);
  entity *get_hero_ptr(int);
};

class game
{
public:
  int get_active_player();
};

extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;
extern void error(const char *, ...);

class item : public entity
{
public:
  enum usage_t
  {
    INVALID = -1,
    INSTANT,
    INVENTORY,
    UTILITY,
    GUN,
    THROWN,
    MELEE,
    AMMO,
    HEALTH,
    ARMOR,
    ENERGY,
    PERMANENT
  };

  usage_t get_usage_type() const;
  virtual int get_count() const;
  virtual void set_count(int);
  virtual int get_number() const;
  virtual bool give_to_entity(entity *);
  void spawn_item_script();
  virtual void apply_effects(entity *);
  void raise_signal(int);
  void disgorge_items(entity *);

  static int PICKUP;
  bool picked_up;
};

bool item::give_to_entity(entity *target)
{
  bool outval = false;

  switch ( get_usage_type() )
  {
    case UTILITY:
    case INVENTORY:
    case GUN:
    case THROWN:
      outval = target->find_like_item(this)? false : true;
      break;
    case INSTANT:
    case PERMANENT:
      outval = true;
      break;
    case AMMO:
    case HEALTH:
    case ARMOR:
    case ENERGY:
      outval = false;
      break;

    default:
      __builtin_trap();
      break;
  }

  if ( outval )
  {
    if ( g_world_ptr->get_current_level_global_script_object() )
      spawn_item_script();
  }

  int old_count = get_number();
  bool force_raise_signal = false;

  switch( get_usage_type() )
  {
    case INSTANT:
      apply_effects( target );
      set_count( 0 );
      break;

    case UTILITY:
    case INVENTORY:
    case GUN:
    case THROWN:
      {
        bool new_item = target->add_item( this );

        if ( new_item )
        {
          g_world_ptr->guarantee_active( this );
          force_raise_signal = true;
        }
      }
      break;

    case AMMO:
      {
      }
      break;

    case HEALTH:
      {
        error ("Health items not supported in KS.");
      }
      break;

    case ARMOR:
      {
        error ("Armor items not supported in KS.");
      }
      break;

    default:
      __builtin_trap();
      break;
  }

  if(old_count != get_number() || force_raise_signal)
    raise_signal( PICKUP );

  if ( outval || get_count()==0 )
    picked_up = true;

  if ( target == g_world_ptr->get_hero_ptr(g_game_ptr->get_active_player()) )
  {
    disgorge_items(target);
  }

  return outval;
}
